mapper.select:
SELECT id, symbol, long_rate, short_rate, rollover_time, effective_from, created_at, updated_at
FROM t_swap_rate
WHERE symbol = #{symbol}
ORDER BY effective_from DESC, id DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM t_trading_hours
WHERE symbol = #{symbol}
  AND day_of_week = #{dayOfWeek}
  AND session_no = #{sessionNo}
  AND effective_from = #{effectiveFrom}

  AND id <> #{excludeId}

mapper.insert:
INSERT INTO t_trading_hours (
    id, symbol, day_of_week, session_no, open_time, close_time,
    timezone, enabled, effective_from, effective_to
) VALUES (
    #{id}, #{symbol}, #{dayOfWeek}, #{sessionNo}, #{openTime}, #{closeTime},
    #{timezone}, #{enabled}, #{effectiveFrom}, #{effectiveTo}
)

